insert into action_de_reference (code, titre, description, leviers, categories) values ('AR001', 'Accompagner des agriculteurs.trices dans la diversification et l''évolution de leurs pratiques et/ou systèmes de production', 'Soutenir techniquement des pratiques et/ou systèmes agroécologiques (diversification des cultures, réduction des intrants agricoles, haies, agroforesterie, légumineuses, agriculture biologique, etc.) permet d''atténuer le changement climatique et de s''adapter à ses conséquences.', ARRAY['elevage_durable', 'pratiques_fertilisation_azotee']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR002', 'Accompagner la création d''espaces-test agricoles pour l''agroécologie', 'Les espaces-test agricoles permettent à des candidat.e.s de tester leur projet de création d''une activité agricole durable, dans un cadre juridique et matériel sécurisé, sur un lieu donné et pour un temps défini.', ARRAY['elevage_durable', 'pratiques_fertilisation_azotee']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR005', 'Accompagner l''approvisionnement local et bio de la restauration collective - gérée par la collectivité', 'Approvisionner la restauration collective en produits locaux issus de l''agriculture biologique vise à la fois à procurer au plus grand nombre une alimentation diversifiée, de grande qualité sanitaire et gustative mais également à encourager des systèmes de production et des circuits de commercialisation du territoire plus durables.', ARRAY['elevage_durable', 'pratiques_fertilisation_azotee']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR006', 'Accompagner l''approvisionnement local et bio de la restauration collective - des acteurs de la restauration privée', 'Accompagner la restauration collective privée à s''approvisionner en produits locaux issus de l''agriculture biologique vise à la fois à procurer au plus grand nombre une alimentation diversifiée, de grande qualité sanitaire et gustative mais également à encourager des systèmes de production et des circuits de commercialisation du territoire plus durables.', ARRAY['elevage_durable', 'pratiques_fertilisation_azotee']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR008', 'Organiser des animations et sensibiliser à la réduction du gaspillage alimentaire', 'Sensibiliser les habitant.e.s aux causes du gaspillage alimentaire et les accompagner dans l''adoption de gestes simples pour éviter de jeter des aliments encore consommables. Des animations pratiques permettent de réduire les déchets à la source, de préserver les ressources mobilisées pour produire les aliments et de diminuer les dépenses des ménages.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR010', 'Mettre en place une politique de mobilité alternative des agents et des élu.e.s', 'Mettre en place une politique de mobilité alternative des agents et des élu.e.s, visant le changement de comportement, en adoptant une approche diversifiée pour couvrir tant les déplacements professionnels que ceux domicile-travail.
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR011', 'Expérimenter des services d''autopartage décarboné', 'L’autopartage est la mise en commun d’un véhicule ou d’une flotte de véhicules. Ce service offre une souplesse d’utilisation à l’usager qui peut louer le véhicule de façon totalement autonome, de sa réservation à sa restitution. Plusieurs organismes privés existent pour accompagner les AOM dans la mise en place de ces services. Les services d’autopartage peuvent être vus comme un moyen pour accompagner la démotorisation des ménages en proposant une alternative ponctuelle et décarbonée quand l’utilisation de la voiture reste nécessaire.', ARRAY['vehicules_electriques', 'velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement', 'sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR012', 'Identifier l''ensemble des axes cyclables potentiels en s’appuyant en priorité sur les voiries secondaires', 'Dans les territoires peu denses, identifier et qualifier des itinéraires s’appuyant en priorité sur les voiries secondaires (routes communales, chemins agricoles et forestiers) afin de relier les communes entre elles, les communes aux zones d’activités économiques, en évitant d’emprunter les routes départementales.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR013', 'Développer un réseau d''itinéraires cyclables d’intérêt communal', 'Dans les territoires peu denses, après identification des axes cyclables intercommunaux potentiels, qualifier puis aménager des itinéraires en s''appuyant en priorité sur les voiries secondaires (routes communales, chemins agricoles et forestiers) afin de relier les communes entre elles, les communes aux zones d''activités économiques, en évitant d''emprunter les routes départementales.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR014', 'Développer une offre de service de location de vélos', 'En déployant des services de location de vélos, la collectivité territoriale permet à ses citoyens de tester l’usage du vélo et d’utiliser un vélo sans en assumer la propriété. Un service de location permet ainsi à des personnes non motorisées d’accéder à une solution de mobilité et de pouvoir se déplacer de façon autonome ; à des personnes motorisées d’utiliser le vélo plutôt que la voiture, et d’envisager notamment pour les ménages bi-motorisés de se séparer de leur deuxième véhicule.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR015', 'Aider à l''acquisition d''un vélo (VAE ou musculaire, cargo, etc.)', 'Mettre en place une aide à l''acquisition d''un vélo musculaire, à assistance électrique, cargo ou adapté afin de lever le frein du coût d''achat et de favoriser son utilisation pour les déplacements du quotidien. Le dispositif peut cibler en priorité les ménages modestes et les usages susceptibles de remplacer des trajets en voiture.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['financement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR016', 'Sensibiliser aux enjeux des mobilités alternatives à la voiture individuelle', 'Sensibiliser aux enjeux des mobilités alternatives à la voiture individuelle/autosolisme, en prenant en compte les publics précaires.', ARRAY['velo_transport_commun', 'covoiturage']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR017', 'Créer du stationnement vélo sécurisé au niveau des pôles générateurs de déplacements et cœurs de bourgs', 'Encourager la pratique du vélo en mettant à disposition les équipements de stationnements nécessaires aux usagers. Ces zones de stationnement doivent être visibles (car sécurisant pour l’utilisateur) et adaptés aux différents types de vélo (en particulier les vélos cargos ou avec remorque, qui ont besoin d’espace supplémentaire). Les systèmes de stationnement longue durée fermés peuvent offrir une solution pour les usagers pratiquant la l''intermodalité.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR018', 'Aménager les aires de covoiturage existantes ou créer de nouvelles aires', 'Créer de nouvelles aires ou contribuer à l''amélioration des aires de covoiturage existantes en favorisant l''intermodalité et en y déployant des services (itinéraires cyclables, stationnements sécurisés vélos, vélos en libre service, arrêt de transport en commun, ventes en direct de produits locaux, aménités d''attente, signalétiques, etc.).', ARRAY['covoiturage', 'velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR019', 'Dédier une démarche en faveur de l''écomobilité scolaire', 'Cibler les jeunes de la maternelle au lycée pour leur permettre d''appréhender les enjeux liés à la mobilité sur le territoire et qu''ils soient encouragés à privilégier des modes de déplacement alternatifs à la voiture individuelle.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement', 'sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR020', 'Former agents et élu.e.s aux enjeux de l''économie circulaire', 'Former les agents et les élu.e.s aux enjeux de l''économie circulaire.', ARRAY['valorisation_matiere_dechets', 'prevention_dechets']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR021', 'Sensibiliser au tri à la source des biodéchets', 'Les biodéchets sont des déchets non dangereux biodégradables de jardin ou de parc et les déchets alimentaires ou de cuisine provenant des ménages, restaurants, commerces, cantines, taiteurs ainsi que les déchets comparable proventant des usine de tranformation de denrées alimentaires. Depuis le 1er janvier 2024, les collectivités territoriales sont tenues de mettre en place un tri à la source des biodéchets pour les particuliers, dans le cadre du service public de gestion des déchets.', ARRAY['valorisation_matiere_dechets']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR022', 'Accompagner le tri à la source des biodéchets', 'Les biodéchets sont des déchets non dangereux biodégradables de jardin ou de parc et les déchets alimentaires ou de cuisine provenant des ménages, restaurants, commerces, cantines, taiteurs ainsi que les déchets comparable proventant des usine de tranformation de denrées alimentaires. Depuis le 1er janvier 2024, les collectivités territoriales sont tenues de mettre en place un tri à la source des biodéchets pour les particuliers, dans le cadre du service public de gestion des déchets.', ARRAY['valorisation_matiere_dechets']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR023', 'Déployer un espace de collecte dédié au réemploi dans les déchèteries', 'Les zones de réemploi en déchèteries permettent aux usagers de venir déposer des objets pour qu''ils puissent être récupérés et réutilisés par des structures de réemploi. Les zones de gratuité quand à elles permettent le dépôt et la récupération d''objets par les usagers de la déchèteries. Ces zones permettent d''organiser la collecte, de les mettre en valeur et leur donner une seconde vie.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR024', 'Promouvoir et encourager les initiatives de réparation sur le territoire', 'Soutenir des initiatives de recyclerie ou de réparation de matériel en proposant des lieux à des associations ou à des acteurs de l’économie social et solidaire qui s’engagent sur cette pratique. Une animation du réseau peut venir amplifier la dynamique et créer une synergie entre les différents acteurs.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['sensibilisation', 'gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR025', 'Réduire le gaspillage alimentaire dans la restauration collective publique', 'Au delà des actions réglementaires comme la pesée du gaspillage dans les cantines, la restauration collective peut agir en faveur de la réduction du gaspillage alimentaire.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR026', 'Réduire le gaspillage alimentaire dans la restauration hors-foyer', 'Accompagner les acteurs de la restauration hors-foyer, notamment la restauration collective privée et la restauration commerciale, dans la réduction du gaspillage alimentaire. La collectivité peut mobiliser les établissements, faciliter leur accès à un diagnostic et à des formations, puis favoriser le partage de solutions adaptées à leurs pratiques d''achat, de préparation et de service.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR027', 'Accompagner les acteurs économiques dans la mise en place d''une démarche de type Ecologie Industrielle Territoriale', 'Les démarches d''Ecologie Industrielle Territoriale (EIT) visent à optimiser les ressources d''un territoire qu''il s''agisse d''énergies, d''eau, de matières, de déchets mais aussi d''équipements et d''expertises via la création de synergies entre les acteurs économiques de ce territoire. Ces synergies vont permettent aux entreprises de réduire leur impact environnemental, de créer des gains économique et donc d''accroitre leur compétitivité.', ARRAY['production_industrielle', 'valorisation_matiere_dechets', 'prevention_dechets']::public.levier_ges_id[], ARRAY['gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR028', 'Soutenir des projets éducatifs autour de la consommation responsable', 'Mettre en place des animations régulières autour du réemploi pour les scolaires avec des ateliers, évènements, animations, projets adaptés en fonction des âges.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR029', 'Maintenir et développer des services et commerces de proximité dans les centres-villes', 'Le maintien et le développement d''une offre de service et de commerces de proximité est indispensable pour redynamiser les centres-villes et centres bourgs à faible attractivité. Cela peut impliquer des investissements dans les infrastructures, des incitations financières pour retenir ou attirer les commerces et les services et pour réhabiliter les bâtiments existants. Cette mesure permet de limiter les déplacements et les distances parcourues des habitant.e.s tout en améliorant leur cadre de vie de proximité.', ARRAY['reduction_deplacements']::public.levier_ges_id[], ARRAY['amenagement', 'sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR032', 'Réaliser des achats durables via la commande publique', 'Mobiliser la commande publique pour réaliser des achats durables sur l''ensemble des produits, bien et services gérés par la collectivité. 
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR034', 'Sensibiliser le grand public aux enjeux de la transition écologique', 'Sensibiliser le grand public au enjeux de la transition écologique en abordant plusieurs thématiques (modes déplacements, choix de consommation, déchets,  habitation, etc.)', ARRAY['velo_transport_commun', 'sobriete_batiments_residentiel', 'prevention_dechets']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR035', 'Mettre en place ou ajouter des critères "environnement" au budget participatif', 'Créer un budget participatif consacré à la transition écologique ou intégrer des critères environnementaux à un dispositif existant. Une enveloppe dédiée permet aux habitant.e.s de proposer et de choisir des projets locaux dont les bénéfices environnementaux sont examinés, puis suivis lors de leur réalisation.', ARRAY['velo_transport_commun', 'sobriete_batiments_residentiel', 'prevention_dechets']::public.levier_ges_id[], ARRAY['financement', 'gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR038', 'Moduler et réduire l''éclairage public', 'Moduler et/ou réduire l’éclairage dans un objectif de moindre impact sur la biodiversité, de réduction des consommations énergétiques et des coûts associés.', ARRAY['sobriete_isolation_batiments_tertiaire']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR039', 'Réaliser un diagnostic de la performance énergétique du patrimoine bâti public', 'Le suivi des consommations énergétiques du patrimoine public bâti permet de gérer au mieux la consommation d’énergie, d’identifier les éventuels dysfonctionnements du patrimoine, ainsi que de bâtir les pistes d’actions pour l’améliorer.', ARRAY['sobriete_isolation_batiments_tertiaire']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR040', 'Accompagner les particuliers pour la rénovation et la construction durable de leur logement', 'L''accompagnement et la communication sur les enjeux de la rénovation et les dispositifs d’aide est importante pour atteindre les objectifs de massification attendus.', ARRAY['sobriete_batiments_residentiel', 'chaudieres_fioul_renovation_residentiel', 'chaudieres_gaz_renovation_residentiel']::public.levier_ges_id[], ARRAY['sensibilisation', 'financement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR041', 'Accompagner les professionnels (artisans, commerçants) dans la rénovation et la construction durable de leur local / bâtiment tertiaire', 'Accompagner les artisans, commerçants et autres occupants ou propriétaires de bâtiments tertiaires dans la rénovation énergétique et la construction durable de leurs locaux. Un conseil adapté à leur activité permet d''identifier les travaux prioritaires, de mobiliser les aides disponibles et d''améliorer le confort tout en réduisant les consommations d''énergie.', ARRAY['sobriete_isolation_batiments_tertiaire', 'chaudiere_fioul_tertiaire', 'chaudiere_gaz_tertiaire']::public.levier_ges_id[], ARRAY['sensibilisation', 'financement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR042', 'Prévenir et lutter contre la précarité énergétique dans les logements', 'Prévenir et lutter contre la précarité énergétique dans les logements.', ARRAY['sobriete_batiments_residentiel']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR043', 'Développer le solaire photovoltaïque dans le résidentiel, les bâtiments industriels et les bâtiments publics', 'Identifier les bâtiments résidentiels, industriels et publics avec un potentiel solaire significatif pour hiérarchiser et orienter les installations de panneaux photovoltaïques.', ARRAY['electricite_renouvelable']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR044', 'Connaître les potentiels d''énergie renouvelable et de récupération, de diminution des émissions et de maîtrise de l''énergie sur le territoire', 'Effectuer de manière conjointe l''analyse des potentiels de développement des énergies renouvelables et de récupération, de maîtrise des consommations d’énergie et de réduction des émissions de GES et polluants atmosphériques.', ARRAY['sobriete_batiments_residentiel', 'sobriete_isolation_batiments_tertiaire', 'electricite_renouvelable', 'biogaz', 'reseaux_chaleur_decarbones']::public.levier_ges_id[], ARRAY['gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR045', 'Accompagner la création, l''extension et l''exploitation d’un réseau de chaleur', 'Un réseau de chaleur est un système de distribution de chaleur produite de façon centralisée, permettant de desservir plusieurs usagers. En milieu rural, il peut s''avérer intéressant voire nécessaire de mutualiser avec d''autres collectivités la mise en œuvre du projet réseau de chaleur. Les réseaux de chaleur permettent d''utiliser efficacement des sources d''énergie renouvelable locales telles que la géothermie profonde ou la chaleur issue des industries et des déchets.', ARRAY['reseaux_chaleur_decarbones']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR052', 'Suivre et réduire, si possible, les consommations d''énergie des stations d''assainissement et d''eau potable', 'Suivre les consommations d''énergie des installations d''eau potable et d''assainissement, puis optimiser les équipements et leur fonctionnement pour réduire les besoins énergétiques du service. La démarche porte notamment sur le pompage, le traitement de l''eau et l''aération des eaux usées, tout en maintenant la qualité du service et des traitements.', ARRAY['production_industrielle']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR053', 'Rénover les logements du patrimoine de la collectivité', 'Rénover les logements détenus ou gérés par la collectivité pour réduire leurs consommations d''énergie, améliorer le confort des occupant.e.s en hiver comme en été et limiter les émissions liées au chauffage. La démarche associe amélioration du bâti, évolution des équipements et accompagnement des occupant.e.s.', ARRAY['sobriete_batiments_residentiel', 'chaudieres_fioul_renovation_residentiel', 'chaudieres_gaz_renovation_residentiel']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR054', 'Accompagner les ménages dans la réduction de leurs consommations d''énergie', 'Accompagner les habitant.e.s dans l''évolution de leurs usages de l''énergie au quotidien, en tenant compte de leur logement, de leurs équipements et de leurs besoins. Des conseils pratiques et un suivi des consommations permettent d''identifier les économies accessibles sans dégrader le confort ni les conditions de vie.', ARRAY['sobriete_batiments_residentiel']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR055', 'Programmer et réaliser la rénovation durable des bâtiments publics', 'Définir une stratégie de rénovation du patrimoine bâti public et réaliser les travaux prioritaires pour réduire les besoins en énergie, améliorer le confort et limiter les impacts environnementaux. La programmation s''appuie sur les diagnostics existants et prend en compte les usages, le confort d''été, la qualité de l''air, l''eau et les matériaux.', ARRAY['sobriete_isolation_batiments_tertiaire', 'prevention_dechets', 'chaudiere_fioul_tertiaire', 'chaudiere_gaz_tertiaire']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR056', 'Construire des bâtiments publics sobres et adaptés au changement climatique', 'Concevoir les nouveaux bâtiments publics pour répondre aux besoins des usagers avec des surfaces, des ressources et des consommations maîtrisées. La collectivité peut intégrer dès la programmation le confort d''été, la qualité de l''air, les économies d''eau, le choix des matériaux et les possibilités de production d''énergie renouvelable.', ARRAY['sobriete_isolation_batiments_tertiaire', 'prevention_dechets', 'electricite_renouvelable']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR057', 'Développer les productions d''énergies renouvelables locales en cohérence avec le potentiel du territoire', 'Définir et piloter une trajectoire de développement des énergies renouvelables à l''échelle du territoire, en articulant les potentiels locaux, les zones d''accélération identifiées et les enjeux environnementaux. La collectivité coordonne les acteurs et les projets, fixe des objectifs et suit la production ainsi que sa contribution aux consommations territoriales.', ARRAY['electricite_renouvelable', 'biogaz']::public.levier_ges_id[], ARRAY['amenagement', 'gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR058', 'Définir et mettre en œuvre une stratégie territoriale de mobilité durable', 'Organiser avec les communes et les acteurs compétents une stratégie de déplacement qui facilite les alternatives à la voiture individuelle. Cette démarche permet de coordonner les services et les aménagements, de hiérarchiser les investissements et de répondre aux besoins de mobilité en tenant compte des enjeux d''air, de climat et d''énergie.', ARRAY['velo_transport_commun', 'covoiturage']::public.levier_ges_id[], ARRAY['planification', 'gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR059', 'Développer une offre de transports collectifs réguliers', 'Développer ou améliorer les lignes de transport collectif pour offrir une alternative adaptée aux déplacements du quotidien. En lien avec l''autorité organisatrice et les opérateurs, la collectivité peut agir sur la desserte, les horaires, les correspondances et la qualité des arrêts, en intégrant l''accessibilité et le confort d''été.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR060', 'Mettre en place ou développer un service de transport à la demande', 'Proposer un service de transport sur réservation pour répondre aux besoins insuffisamment couverts par les lignes régulières, notamment dans les secteurs peu denses. Le service doit être facile à utiliser et articulé avec les autres modes de déplacement, en tenant compte des besoins des personnes peu mobiles et du confort d''été.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR061', 'Aménager des cheminements piétons continus et accessibles', 'Faciliter les déplacements à pied en reliant les logements, les services, les commerces et les équipements par des parcours continus, sûrs et accessibles. Les aménagements peuvent améliorer le confort de marche, notamment pour les personnes à mobilité réduite et lors des fortes chaleurs.', ARRAY['velo_transport_commun']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR062', 'Optimiser et décarboner la flotte de véhicules de la collectivité', 'Adapter le nombre, le type et la motorisation des véhicules aux besoins réels des services pour réduire les consommations et les émissions de la flotte. La démarche associe mutualisation, renouvellement progressif et mise en place des infrastructures nécessaires, tout en maintenant la capacité d''intervention des agents.', ARRAY['vehicules_electriques', 'bus_cars_decarbones']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR063', 'Déployer des infrastructures de recharge pour les véhicules électriques', 'Faciliter l''usage des véhicules électriques en développant une offre de recharge cohérente avec les besoins des habitant.e.s, des professionnels et des visiteurs. La collectivité peut coordonner les implantations et les opérateurs pour assurer un service accessible, fiable et complémentaire des équipements existants.', ARRAY['vehicules_electriques']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR064', 'Organiser une logistique territoriale plus sobre et moins polluante', 'Améliorer l''organisation des transports de marchandises et des livraisons pour limiter les déplacements inutiles, les émissions et les nuisances. La collectivité peut réunir les acteurs économiques et agir sur les aménagements, les conditions de livraison et la mutualisation des moyens, selon les besoins du territoire.', ARRAY['efficacite_sobriete_logistique', 'fret_decarbone_multimodalite']::public.levier_ges_id[], ARRAY['gouvernance', 'amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR065', 'Construire et animer une stratégie territoriale d''alimentation durable', 'Mobiliser les acteurs agricoles, alimentaires, sociaux et économiques autour d''une stratégie commune d''alimentation durable, notamment à travers un projet alimentaire territorial. La démarche vise à coordonner les actions, à améliorer l''accès à une alimentation de qualité et à renforcer la résilience et la souveraineté alimentaires du territoire.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['planification', 'gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR067', 'Définir et mettre en œuvre une stratégie de prévention des déchets', 'Organiser à l''échelle du territoire une stratégie pour réduire les quantités de déchets produites par les ménages et les activités économiques concernées. La démarche permet de fixer des priorités, de coordonner les actions existantes et de suivre leurs résultats, notamment dans le cadre d''un programme local de prévention des déchets ménagers et assimilés.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['planification', 'gouvernance']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR068', 'Améliorer la collecte et le tri à la source des déchets', 'Adapter l''organisation de la collecte et les moyens de tri aux besoins des usagers pour améliorer la qualité du service et des flux collectés. La démarche concerne les déchets ménagers et assimilés, y compris ceux des activités économiques prises en charge, en articulation avec les actions de prévention et de gestion des biodéchets.', ARRAY['valorisation_matiere_dechets']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR069', 'Améliorer le traitement et la valorisation des déchets', 'Organiser des filières de tri après collecte, de traitement et de valorisation adaptées aux déchets du territoire. La collectivité peut améliorer la qualité des matières récupérées, sécuriser les débouchés et réduire les déchets résiduels, en cohérence avec la prévention, le réemploi et les possibilités de recyclage.', ARRAY['valorisation_matiere_dechets']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR070', 'Réduire les consommations et les émissions des installations industrielles publiques (notamment traitement des déchets)', 'Améliorer la sobriété, l''efficacité énergétique et la décarbonation des installations industrielles de la collectivité, notamment celles de traitement des déchets. La démarche porte sur les procédés, les équipements et leur exploitation, avec un suivi des émissions atmosphériques. Les installations d''eau et d''assainissement font l''objet d''une action dédiée.', ARRAY['production_industrielle']::public.levier_ges_id[], ARRAY['exemplarite']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR071', 'Accompagner les entreprises industrielles dans leur transition écologique', 'Accompagner les entreprises industrielles pour réduire leurs émissions et leurs consommations d''eau, d''énergie et de matières, tout en préparant leurs activités aux effets du changement climatique. La collectivité peut mobiliser les acteurs du conseil, faciliter les diagnostics et soutenir des projets individuels ou collectifs adaptés aux sites.', ARRAY['production_industrielle']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR079', 'Réhabiliter les espaces urbains délaissés et mutualiser les usages des bâtiments', 'Réutiliser les friches urbaines et les bâtiments sous-utilisés pour répondre aux besoins du territoire en limitant la consommation de nouveaux espaces. La collectivité peut organiser leur reconversion et favoriser la coexistence ou l''alternance de plusieurs usages dans des équipements adaptés.', ARRAY['prevention_dechets']::public.levier_ges_id[], ARRAY['amenagement']::public.volet_categorie[]);
insert into action_de_reference (code, titre, description, leviers, categories) values ('AR080', 'Accompagner la remise en usage des logements vacants', 'Mobiliser les logements durablement vacants pour améliorer l''offre de logements et limiter le recours à de nouvelles constructions. La collectivité peut identifier les causes de la vacance, dialoguer avec les propriétaires et coordonner les solutions de rénovation, de gestion ou de remise sur le marché.', ARRAY['sobriete_batiments_residentiel']::public.levier_ges_id[], ARRAY['sensibilisation']::public.volet_categorie[]);
